<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>2048 Game</title>
    <style>
        :root {
            --bg-color: #121212;
            --grid-bg: #2a2a2a;
            --cell-bg: #333333;
            --text-color: #eeeeee;
            --accent-color: #ffb74d;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            overflow: hidden;
        }

        #game-container {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 20px;
        }

        #score-container {
            font-size: 24px;
            font-weight: bold;
        }

        #board {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            grid-template-rows: repeat(4, 1fr);
            gap: 10px;
            background-color: var(--grid-bg);
            padding: 10px;
            border-radius: 8px;
            width: 320px;
            height: 320px;
        }

        .cell {
            width: 70px;
            height: 70px;
            background-color: var(--cell-bg);
            border-radius: 4px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 28px;
            font-weight: bold;
            transition: background-color 0.15s ease-in-out, transform 0.1s ease-in-out;
        }

        /* Tile Colors */
        .tile-0 { color: transparent; }
        .tile-2 { background-color: #eee4da; color: #776e65; }
        .tile-4 { background-color: #ede0c8; color: #776e65; }
        .tile-8 { background-color: #f2b179; color: #f9f7f7; }
        .tile-16 { background-color: #f59563; color: #f9f7f7; }
        .tile-32 { background-color: #f67c5f; color: #f9f7f7; }
        .tile-64 { background-color: #f65e3b; color: #f9f7f7; }
        .tile-128 { background-color: #edcf7a; color: #f9f7f7; font-size: 24px; }
        .tile-256 { background-color: #edcc61; color: #f9f7f7; font-size: 24px; }
        .tile-512 { background-color: #edc850; color: #f9f7f7; font-size: 24px; }
        .tile-1024 { background-color: #edc53f; color: #f9f7f7; font-size: 20px; }
        .tile-2048 { background-color: #edc22e; color: #f9f7f7; font-size: 20px; }

        #reset {
            padding: 10px 25px;
            font-size: 18px;
            background-color: var(--accent-color);
            border: none;
            border-radius: 5px;
            cursor: pointer;
            font-weight: bold;
            transition: opacity 0.2s;
        }

        #reset:hover {
            opacity: 0.8;
        }
    </style>
</head>
<body>

<div id="game-container">
    <div id="score-container">Score: <span id="score">0</span></div>
    <div id="board"></div>
    <button id="reset">New Game</button>
            </div>

<script>
(function() {
    class Game2048 {
        constructor() {
            this.size = 4;
            this.grid = Array(4).fill(null).map(() => Array(4).fill(0));
            this.scoreValue = 0;
            this.init();
        }

        init() {
            // Resetting logic is called in the reset method via window exposure
            // but we need an initial state here.
            this.reset();
        }

        reset() {
            this.grid = Array(4).fill(null).map(() => Array(4).fill(0));
            this.scoreValue = 0;
            this.addRandomTile();
            this.addRandomTile();
            this.render();
        }

        addRandomTile() {
            let emptyCells = [];
            for (let r = 0; r < 4; r++) {
                for (let c = 0; c < 4; c++) {
                    if (this.grid[r][c] === 0) emptyCells.push([r, c]);
                }
            }
            if (emptyCells.length > 0) {
                const [r, c] = emptyCells[Math.floor(Math.random() * emptyCells.length)];
                this.grid[r][c] = Math.random() < 0.9 ? 2 : 4;
            }
        }

        setBoard(arr) {
            // deep copy to prevent external mutation
            this.grid = arr.map(row => [...row]);
            this.render();
        }

        board() {
            return this.grid.map(row => [...row]);
        }

        score() {
            return this.scoreValue;
        }

        move(direction) {
            let changed = false;
            let scoreDelta = 0;
            const oldBoardStr = JSON.stringify(this.grid);

            // We'll process rows for horizontal and cols for vertical
            for (let i = 0; i < 4; i++) {
                let lineIndices = [];
                if (direction === 'left' || direction === 'right') {
                    lineIndices = [0, 1, 2, 3].map(j => [i, j]);
                    if (direction === 'right') lineIndices.reverse();
                } else {
                    lineIndices = [0, 1, 2, 3].map(j => [j, i]);
                    if (direction === 'down') lineIndices.reverse();
                }

                let values = lineIndices.map(([r, c]) => this.grid[r][c]);

                // Merge Logic
                let nonZeros = values.filter(v => v !== 0);
                let mergedValues = [];
                for (let k = 0; k < nonZeros.length; k++) {
                    if (k < nonZeros.length - 1 && nonZeros[k] === nonZeros[k + 1]) {
                        const newValue = nonZeros[k] * 2;
                        mergedValues.push(newValue);
                        scoreDelta += newValue;
                        k++; // Skip next element
                    } else {
                        mergedValues.push(nonZeros[k]);
                    }
                }
                // Pad with zeros
                while (mergedValues.length < 4) mergedValues.push(0);

                // Place back into grid
                for (let k = 0; k < 4; k++) {
                    const [r, c] = lineIndices[k];
                    this.grid[r][c] = mergedValues[k];
                }
            }

            if (JSON.stringify(this.grid) !== oldBoardStr) {
                changed = true;
                this.scoreValue += scoreDelta;
                this.addRandomTile();
            }

            this.render();
            return changed;
        }

        render() {
            const boardEl = document.getElementById('board');
            const scoreEl = document.getElementById('score');
            boardEl.innerHTML = '';
            scoreEl.textContent = this.scoreValue;

            for (let r = 0; r < 4; r++) {
                for (let c = 0; c < 4; c++) {
                    const val = this.grid[r][c];
                    const cell = document.createElement('div');
                    cell.className = `cell tile-${val}`;
                    cell.textContent = val === 0 ? '' : val;
                    boardEl.appendChild(cell);
                }
            }
        }
    }

    const gameInstance = new Game2048();
    window.game = {
        size: 4,
        reset: () => gameInstance.reset(),
        move: (dir) => gameInstance.move(dir),
        board: () => gameInstance.board(),
        setBoard: (arr) => gameInstance.setBoard(arr),
        score: () => gameInstance.score()
    };

    // Event Listeners
    document.getElementById('reset').addEventListener('click', () => window.game.reset());

    window.addEventListener('keydown', (e) => {
        let moved = false;
        if (e.key === 'ArrowUp') moved = window.game.move('up');
        else if (e.key === 'ArrowDown') moved = window.game.move('down');
        else if (e.key === 'ArrowLeft') moved = window.game.move('left');
        else if (e.key === 'ArrowRight') moved = window.game.move('right');

        if (moved) e.preventDefault();
    }, { passive: false });

})();
</script>
</body>
</html>
